-- F2B SHOP: NEW COLOUR-MATCHED 64-PRODUCT CATALOGUE
-- Created for existing f2b_shop MySQL schema (categories/products).
-- Match strategy: product NAME and COLOUR are taken from the same dataset entry
-- as the four gallery photos (same product_id, numbered 1 through 4).
-- Unlike previous seeds, no unrelated photo is assigned to a prewritten product.
-- Source: https://github.com/pazhanir/product-images
-- Photo host: https://pazhanir.github.io/product-images/
-- A third-party dataset supplies product names, primary colours, review data and
-- photo mappings; the storefront prices/discounts here are ILLUSTRATIVE in $.
-- Photos and metadata are third-party data: check licensing before public use.
-- URL existence has been checked against the GitHub repository tree, but image
-- content/colour and live HTTP availability have NOT been visually verified.
--
-- IMPORTANT FOR EXISTING DATABASES:
--   * Back up/export your existing f2b_shop database before importing.
--   * Only categories 1-6 and products with IDs 1-64 are inserted/updated.
--   * No tables are dropped; orders, order_items and mockup/review tables remain.
--   * Product IDs 1-64 are retained, so existing foreign keys do not break.
--   * However, this replaces the identity/details of products previously at IDs
--     1-64. Existing order_item snapshots remain unchanged; historical orders
--     may show the new product image when joining products by ID.
--   * This is intended for a DEMO database, not a production store with real orders.
--   * Re-importing this file updates the same IDs; it will not duplicate them.
--   * Extra products with IDs >64 (if any) remain untouched.
--
-- Use phpMyAdmin > select f2b_shop > Import; requires schema.sql already imported.

USE f2b_shop;

START TRANSACTION;

INSERT INTO categories (id, name, slug) VALUES
    (1, 'T-Shirts', 't-shirts'),
    (2, 'Shirts', 'shirts'),
    (3, 'Hoodies & Sweatshirts', 'hoodies'),
    (4, 'Jackets', 'jackets'),
    (5, 'Pants', 'pants'),
    (6, 'Accessories', 'accessories')
ON DUPLICATE KEY UPDATE name = VALUES(name), slug = VALUES(slug);

-- Use stable IDs so re-import does not duplicate the catalogue.
-- Genuine product photographs: four numbered views are from the SAME dataset item.
INSERT INTO products (
  id, category_id, name, slug, description, price, original_price,
  rating, review_count, image, image_2, image_3, image_4, colour,
  is_new, is_top_selling, created_at
) VALUES
