  (64, 6, 'Red Leather Structured Shoulder Bag', 'catalog-17761230', 'Red Leather Structured Shoulder Bag. Source catalogue brand: Caprese. Listed colour: Red. The gallery shows four images from the same product listing. Demo pricing for coursework.', 84.90, 102.73, 4.1, 10, 'https://pazhanir.github.io/product-images/BagsAndWallets/handbags/17761230_1.jpg', 'https://pazhanir.github.io/product-images/BagsAndWallets/handbags/17761230_2.jpg', 'https://pazhanir.github.io/product-images/BagsAndWallets/handbags/17761230_3.jpg', 'https://pazhanir.github.io/product-images/BagsAndWallets/handbags/17761230_4.jpg', 'Red', 0, 0, '2026-10-21 10:00:00')
ON DUPLICATE KEY UPDATE
  category_id=VALUES(category_id),
  name=VALUES(name),
  slug=VALUES(slug),
  description=VALUES(description),
  price=VALUES(price),
  original_price=VALUES(original_price),
  rating=VALUES(rating),
  review_count=VALUES(review_count),
  image=VALUES(image),
  image_2=VALUES(image_2),
  image_3=VALUES(image_3),
  image_4=VALUES(image_4),
  colour=VALUES(colour),
  is_new=VALUES(is_new),
  is_top_selling=VALUES(is_top_selling),
  created_at=VALUES(created_at);

COMMIT;

-- Validation: expected 64 rows with IDs 1..64; more if other products existed.
SELECT COUNT(*) AS seeded_catalogue_rows
FROM products WHERE id BETWEEN 1 AND 64;

SELECT c.name AS category_name, COUNT(p.id) AS product_count
FROM categories c LEFT JOIN products p ON p.category_id=c.id AND p.id BETWEEN 1 AND 64
GROUP BY c.id, c.name ORDER BY c.id;

SELECT id, name, colour, image, image_2
FROM products WHERE id BETWEEN 1 AND 64 ORDER BY id LIMIT 12;
